const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountIsa = ee.Geometry.Point([139.4926, -20.7256]).buffer(50000); // 50km buffer around Mount Isa
  const townsville = ee.Geometry.Point([146.8169, -19.2590]).buffer(50000); // 50km buffer around Townsville

  const startDate = '2019-01-27';
  const endDate = '2019-02-10';

  // 2. Data Acquisition - CHIRPS daily precipitation
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .select('precipitation');

  const collectionSize = chirps.size().getInfo();
  console.log(`CHIRPS images in period: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No precipitation data found for the period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum rainfall over the period
  const totalRainfall = chirps.sum();

  // Check valid pixels for both regions
  const mountIsaCount = totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mountIsa,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const townsvilleCount = totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: townsville,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Mount Isa valid pixels: ${mountIsaCount}`);
  console.log(`Townsville valid pixels: ${townsvilleCount}`);

  if (mountIsaCount === 0 || townsvilleCount === 0) {
    console.log("No valid precipitation pixels in one or both regions.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean rainfall for each region
  const mountIsaRainfall = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: mountIsa,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const townsvilleRainfall = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: townsville,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Mount Isa total rainfall (mm): ${mountIsaRainfall ? mountIsaRainfall.toFixed(1) : 'null'}`);
  console.log(`Townsville total rainfall (mm): ${townsvilleRainfall ? townsvilleRainfall.toFixed(1) : 'null'}`);

  // 5. Validation & Final Answer
  if (mountIsaRainfall === null || townsvilleRainfall === null || 
      isNaN(mountIsaRainfall) || isNaN(townsvilleRainfall)) {
    console.log("Invalid rainfall calculation result.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if either region exceeded 650mm (65cm)
  const mountIsaExceeded = mountIsaRainfall > 650;
  const townsvilleExceeded = townsvilleRainfall > 650;

  console.log(`Mount Isa >650mm: ${mountIsaExceeded}`);
  console.log(`Townsville >650mm: ${townsvilleExceeded}`);

  if (mountIsaExceeded || townsvilleExceeded) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
